-- risk: additive
--
-- 0268 (#1654) -- the template field registry names `memberGettingStarted`.
--
-- 0267 added the flag to `feature_registry()` and to the association
-- builtin; the template field registry of 0265/0266 (#1655) lists every
-- feature flag as a field a template may carry, one record per
-- `workspace.feature_flags.<key>`, and `template_field_registry_sql_test`
-- fails until the latest definition carries the generated JSON exactly.
-- An applied file never changes, so the registry is restated here,
-- GENERATED by `dart run tool/build_template_field_registry_sql.dart`:
-- the one new record is the flag's, `portability: literal`, absent means
-- the registry default (ON), like every other flag's.
--
-- Nothing else travels with this: no table, no policy, no other function.

create or replace function public.template_field_registry()
returns jsonb
language sql
immutable
set search_path = public
as $registry$
